def search_notes(keywords, limit=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None, started=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limited(endpoint, per_minute=60):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-2000:]):
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            c += 1
            if c >= per_minute:
                return True
        return False

    started = time.time()
    endpoint = "search_notes"

    # Validate
    if not isinstance(keywords, str):
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "keywords_type"})
        return _err("VALIDATION_ERROR", "keywords must be a string")
    kw = keywords.strip()
    if not kw:
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "keywords_empty"})
        return _err("VALIDATION_ERROR", "keywords must not be empty")
    if limit is None:
        lim = 10
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            _log(endpoint, "VALIDATION_ERROR", meta={"reason": "limit_type"})
            return _err("VALIDATION_ERROR", "limit must be a number")
        lim = int(limit)
    if lim < 1 or lim > 50:
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "limit_range", "limit": lim})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 50")

    # Rate limit
    if _rate_limited(endpoint, per_minute=60):
        _log(endpoint, "RATE_LIMIT", meta={"reason": "per_minute"})
        return _err("RATE_LIMIT", "Too many requests, please retry later")

    # Need an active session somewhere
    sessions = _load("auth_sessions.json")
    accounts = _load("accounts.json")
    active_session = None
    for s in sessions:
        if s.get("status") != "active":
            continue
        acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
        if not acc or acc.get("platform") != "rednote" or acc.get("status") != "active":
            continue
        # check expires_at if present
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp < datetime.datetime.utcnow():
            continue
        active_session = s
        break
    if not active_session:
        _log(endpoint, "UNAUTHORIZED", meta={"reason": "no_active_session"})
        return _err("UNAUTHORIZED", "No valid active session available")

    # Create query record: queued -> running -> completed/failed
    queries = _load("search_queries.json")
    results = _load("search_query_results.json")
    notes = _load("notes.json")

    now = _now()
    qid = "sq_" + hashlib.sha256(f"{kw}|{lim}|{now}|{len(queries)}".encode("utf-8")).hexdigest()[:16]
    qrow = {
        "id": qid,
        "keywords": kw,
        "limit": lim,
        "status": "queued",
        "executed_at": None,
        "result_count": 0,
        "error": None,
        "created_at": now,
        "updated_at": now,
    }
    queries.append(qrow)
    try:
        _save("search_queries.json", queries)
    except Exception:
        _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_query_failed"}, started=started)
        return _err("CONFLICT", "Failed to persist query")

    # Transition queued->running
    for q in queries:
        if q.get("id") == qid:
            if q.get("status") != "queued":
                _log(endpoint, "INVALID_TRANSITION", credential_id=active_session.get("id"), meta={"query_id": qid}, started=started)
                return _err("INVALID_TRANSITION", "Invalid query state transition")
            q["status"] = "running"
            q["executed_at"] = _now()
            q["updated_at"] = _now()
            break
    try:
        _save("search_queries.json", queries)
    except Exception:
        _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_running_failed"}, started=started)
        return _err("CONFLICT", "Failed to update query status")

    # Perform local search over cached notes (real upstream omitted; unauthorized handled above)
    tokens = [t for t in re.split(r"\s+", kw) if t]
    def _hay(n):
        parts = [
            n.get("title") or "",
            n.get("content_text") or "",
            n.get("author_name") or "",
            " ".join(n.get("tags") or []) if isinstance(n.get("tags"), list) else "",
            n.get("url") or "",
        ]
        return " ".join(parts).lower()

    scored = []
    for n in notes:
        if n.get("platform") != "rednote":
            continue
        if n.get("status") in ("deleted",):
            continue
        h = _hay(n)
        if not h.strip():
            continue
        # require all tokens present
        ok = True
        for t in tokens:
            if t.lower() not in h:
                ok = False
                break
        if not ok:
            continue
        score = sum(h.count(t.lower()) for t in tokens)
        scored.append((score, n))
    scored.sort(key=lambda x: (-x[0], x[1].get("updated_at") or "", x[1].get("id") or ""))
    matched = [n for _, n in scored[:lim]]

    # Write results rows with unique (query_id, rank) and (query_id, note_id)
    # Remove any pre-existing rows for this query_id (should be none, but keep idempotent for retries)
    results = [r for r in results if r.get("query_id") != qid]
    created = 0
    for idx, n in enumerate(matched, start=1):
        rid = "sqr_" + hashlib.sha256(f"{qid}|{n.get('id')}|{idx}".encode("utf-8")).hexdigest()[:16]
        snippet = None
        ct = (n.get("content_text") or "").strip()
        if ct:
            snippet = ct[:120]
        rrow = {
            "id": rid,
            "query_id": qid,
            "note_id": n.get("id"),
            "rank": idx,
            "score": float(max(0, scored[idx - 1][0])) if idx - 1 < len(scored) else None,
            "snippet": snippet,
            "created_at": _now(),
            "updated_at": _now(),
        }
        results.append(rrow)
        created += 1

    # Transition running->completed
    for q in queries:
        if q.get("id") == qid:
            if q.get("status") != "running":
                _log(endpoint, "INVALID_TRANSITION", credential_id=active_session.get("id"), meta={"query_id": qid}, started=started)
                return _err("INVALID_TRANSITION", "Invalid query state transition")
            q["status"] = "completed"
            q["result_count"] = int(created)
            q["error"] = None
            q["updated_at"] = _now()
            break

    try:
        _save("search_query_results.json", results)
        _save("search_queries.json", queries)
    except Exception:
        # If persistence fails, mark failed (best effort) with legal transition running->failed only; but we already set completed.
        # Return conflict rather than lying about success.
        _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_results_failed", "query_id": qid}, started=started)
        return _err("CONFLICT", "Failed to persist search results")

    _log(endpoint, "ok", credential_id=active_session.get("id"), meta={"query_id": qid, "result_count": created}, started=started)
    return {
        "query": {"id": qid, "keywords": kw, "limit": lim, "status": "completed", "result_count": created},
        "notes": matched,
        "meta": {"total": created, "limit": lim, "has_more": False, "next_cursor": None},
    }

def get_note_content(url, **_extra):
    import json, os, datetime, time, hashlib, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None, started=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limited(endpoint, per_minute=120):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-3000:]):
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            c += 1
            if c >= per_minute:
                return True
        return False

    def _valid_url(u):
        if not isinstance(u, str):
            return False
        uu = u.strip()
        if not uu:
            return False
        try:
            p = urllib.parse.urlparse(uu)
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        if not p.netloc:
            return False
        return True

    def _extract_note_key(u):
        try:
            p = urllib.parse.urlparse(u)
            path = p.path or ""
            m = re.search(r"/(explore|discovery|note|notes)/([A-Za-z0-9]+)", path)
            if m:
                return m.group(2)
            # fallback: last path segment if alnum length >= 6
            seg = [s for s in path.split("/") if s]
            if seg:
                last = seg[-1]
                if re.fullmatch(r"[A-Za-z0-9]{6,}", last):
                    return last
        except Exception:
            return None
        return None

    started = time.time()
    endpoint = "get_note_content"

    # Validate
    if not _valid_url(url):
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "bad_url"})
        return _err("VALIDATION_ERROR", "url is missing or invalid")
    url = url.strip()

    # Rate limit
    if _rate_limited(endpoint, per_minute=120):
        _log(endpoint, "RATE_LIMIT", meta={"reason": "per_minute"})
        return _err("RATE_LIMIT", "Too many requests, please retry later")

    # Need active session
    sessions = _load("auth_sessions.json")
    accounts = _load("accounts.json")
    active_session = None
    for s in sessions:
        if s.get("status") != "active":
            continue
        acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
        if not acc or acc.get("platform") != "rednote" or acc.get("status") != "active":
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp and exp < datetime.datetime.utcnow():
            continue
        active_session = s
        break
    if not active_session:
        _log(endpoint, "UNAUTHORIZED", meta={"reason": "no_active_session"})
        return _err("UNAUTHORIZED", "No valid active session available")

    notes = _load("notes.json")
    now = _now()

    note = next((n for n in notes if n.get("platform") == "rednote" and n.get("url") == url), None)

    # If cached available, return without mutation
    if note and note.get("status") == "available":
        _log(endpoint, "ok", credential_id=active_session.get("id"), meta={"cache": "hit", "note_id": note.get("id")}, started=started)
        return {"note": note, "meta": {"cache": "hit"}}

    # If not exists create discovered
    if not note:
        nid = "note_" + hashlib.sha256(f"rednote|{url}|{now}|{len(notes)}".encode("utf-8")).hexdigest()[:16]
        nk = _extract_note_key(url)
        # enforce unique(platform, note_key) where note_key not null
        if nk:
            for n in notes:
                if n.get("platform") == "rednote" and n.get("note_key") and n.get("note_key") == nk:
                    _log(endpoint, "CONFLICT", credential_id=active_session.get("id"), meta={"reason": "note_key_conflict", "note_key": nk}, started=started)
                    return _err("CONFLICT", "note_key already exists for another note")
        note = {
            "id": nid,
            "platform": "rednote",
            "url": url,
            "note_key": nk,
            "author_name": None,
            "title": None,
            "content_text": None,
            "content_html": None,
            "media_urls": None,
            "tags": None,
            "published_at": None,
            "status": "discovered",
            "last_fetched_at": None,
            "fetch_error": None,
            "created_at": now,
            "updated_at": now,
        }
        notes.append(note)
        try:
            _save("notes.json", notes)
        except Exception:
            _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_discovered_failed"}, started=started)
            return _err("CONFLICT", "Failed to create note record")

    # Transition to fetching (respect lifecycle, and deleted can't go back to available)
    allowed = {
        "discovered": ["fetching", "unavailable"],
        "fetching": ["available", "unavailable"],
        "available": ["fetching", "deleted", "unavailable"],
        "unavailable": ["fetching", "deleted"],
        "deleted": [],
    }
    cur = note.get("status")
    if cur == "deleted":
        _log(endpoint, "NOT_FOUND", credential_id=active_session.get("id"), meta={"reason": "note_deleted", "note_id": note.get("id")}, started=started)
        return _err("NOT_FOUND", "Note is deleted or unavailable")

    if "fetching" not in allowed.get(cur, []):
        _log(endpoint, "INVALID_TRANSITION", credential_id=active_session.get("id"), meta={"from": cur, "to": "fetching", "note_id": note.get("id")}, started=started)
        return _err("INVALID_TRANSITION", "Invalid note status transition")

    # apply fetching transition
    for n in notes:
        if n.get("id") == note.get("id"):
            n["status"] = "fetching"
            n["fetch_error"] = None
            n["updated_at"] = _now()
            note = n
            break
    try:
        _save("notes.json", notes)
    except Exception:
        _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_fetching_failed", "note_id": note.get("id")}, started=started)
        return _err("CONFLICT", "Failed to update note status")

    # "Fetch" simulation from cache only: if no content in store, treat as not found/unavailable
    # Success criteria: some minimal fields exist (title or content_text)
    has_content = bool((note.get("title") or "").strip() or (note.get("content_text") or "").strip())
    if not has_content:
        # Transition fetching->unavailable
        for n in notes:
            if n.get("id") == note.get("id"):
                if "unavailable" not in allowed.get(n.get("status"), []):
                    _log(endpoint, "INVALID_TRANSITION", credential_id=active_session.get("id"), meta={"from": n.get("status"), "to": "unavailable"}, started=started)
                    return _err("INVALID_TRANSITION", "Invalid note status transition")
                n["status"] = "unavailable"
                n["fetch_error"] = "content not cached and upstream fetch unavailable"
                n["last_fetched_at"] = None
                n["updated_at"] = _now()
                note = n
                break
        try:
            _save("notes.json", notes)
        except Exception:
            _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_unavailable_failed", "note_id": note.get("id")}, started=started)
            return _err("CONFLICT", "Failed to persist fetch result")
        _log(endpoint, "NOT_FOUND", credential_id=active_session.get("id"), meta={"note_id": note.get("id"), "cache": "miss"}, started=started)
        return _err("NOT_FOUND", "Note not found or not accessible")

    # Transition fetching->available (but never from deleted; already handled)
    for n in notes:
        if n.get("id") == note.get("id"):
            if "available" not in allowed.get(n.get("status"), []):
                _log(endpoint, "INVALID_TRANSITION", credential_id=active_session.get("id"), meta={"from": n.get("status"), "to": "available"}, started=started)
                return _err("INVALID_TRANSITION", "Invalid note status transition")
            n["status"] = "available"
            n["last_fetched_at"] = _now()
            n["fetch_error"] = None
            n["updated_at"] = _now()
            note = n
            break
    try:
        _save("notes.json", notes)
    except Exception:
        _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_available_failed", "note_id": note.get("id")}, started=started)
        return _err("CONFLICT", "Failed to persist note content")

    _log(endpoint, "ok", credential_id=active_session.get("id"), meta={"cache": "refresh", "note_id": note.get("id")}, started=started)
    return {"note": note, "meta": {"cache": "refresh"}}

