        return _err("UNAUTHORIZED", "No valid active session available")

    notes = _load("notes.json")
    comments = _load("comments.json")
    now = _now()

    note = next((n for n in notes if n.get("platform") == "rednote" and n.get("url") == url), None)
    if not note:
        nid = "note_" + hashlib.sha256(f"rednote|{url}|{now}|{len(notes)}".encode("utf-8")).hexdigest()[:16]
        nk = _extract_note_key(url)
        if nk:
            for n in notes:
                if n.get("platform") == "rednote" and n.get("note_key") and n.get("note_key") == nk:
                    _log(endpoint, "CONFLICT", credential_id=active_session.get("id"), meta={"reason": "note_key_conflict", "note_key": nk}, started=started)
                    return _err("CONFLICT", "note_key already exists for another note")
        note = {
            "id": nid,
            "platform": "rednote",
            "url": url,
            "note_key": nk,
            "author_name": None,
            "title": None,
            "content_text": None,
            "content_html": None,
            "media_urls": None,
            "tags": None,
            "published_at": None,
            "status": "discovered",
            "last_fetched_at": None,
            "fetch_error": None,
            "created_at": now,
            "updated_at": now,
        }
        notes.append(note)
        try:
            _save("notes.json", notes)
        except Exception:
            _log(endpoint, "failed", credential_id=active_session.get("id"), meta={"reason": "persist_discovered_failed"}, started=started)
            return _err("CONFLICT", "Failed to create note record")

    if note.get("status") == "deleted":
        _log(endpoint, "NOT_FOUND", credential_id=active_session.get("id"), meta={"reason": "note_deleted", "note_id": note.get("id")}, started=started)
        return _err("NOT_FOUND", "Note not found or not accessible")

    # Return cached if exists
    cached = [c for c in comments if c.get("note_id") == note.get("id") and c.get("status") == "visible"]
    if cached:
        cached.sort(key=lambda x: (x.get("commented_at") or x.get("created_at") or "", x.get("id") or ""))
        _log(endpoint, "ok", credential_id=active_session.get("id"), meta={"cache": "hit", "note_id": note.get("id"), "count": len(cached)}, started=started)
        return {"note_id": note.get("id"), "comments": cached, "meta": {"cache": "hit", "total": len(cached)}}

    # No upstream available offline; treat as not found for comments source if none cached
    _log(endpoint, "NOT_FOUND", credential_id=active_session.get("id"), meta={"cache": "miss", "note_id": note.get("id")}, started=started)
    return _err("NOT_FOUND", "Comments not found or not accessible")

def login(username, password, user_agent=None, ip_address=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None, started=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limited(endpoint, per_minute=10):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-2000:]):
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            c += 1
            if c >= per_minute:
                return True
        return False

    started = time.time()
    endpoint = "login"

    # Validate
    if not isinstance(username, str) or not username.strip():
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "username"})
        return _err("VALIDATION_ERROR", "username is required")
    if not isinstance(password, str) or not password.strip():
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "password"})
        return _err("VALIDATION_ERROR", "password is required")
    uname = username.strip()

    if user_agent is not None and (not isinstance(user_agent, str) or not user_agent.strip()):
        _log(endpoint, "VALIDATION_ERROR", meta={"reason": "user_agent"})
        return _err("VALIDATION_ERROR", "user_agent must be a non-empty string if provided")
    if ip_address is not None:
        if not isinstance(ip_address, str) or not ip_address.strip():
            _log(endpoint, "VALIDATION_ERROR", meta={"reason": "ip_address"})
            return _err("VALIDATION_ERROR", "ip_address must be a non-empty string if provided")
        ip = ip_address.strip()
        # light validation
        if not re.fullmatch(r"[0-9a-fA-F\.\:]{3,45}", ip):
            _log(endpoint, "VALIDATION_ERROR", meta={"reason": "ip_format"})
            return _err("VALIDATION_ERROR", "ip_address format is invalid")

    if _rate_limited(endpoint, per_minute=10):
        _log(endpoint, "RATE_LIMIT", meta={"reason": "per_minute"})
        return _err("RATE_LIMIT", "Too many login attempts, please retry later")

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")
    now = _now()

    # Authenticate: in this offline datastore, treat existing active account with matching username as valid if password is non-empty
    acc = next((a for a in accounts if a.get("platform") == "rednote" and a.get("username") == uname), None)
    if not acc:
        _log(endpoint, "UNAUTHORIZED", meta={"reason": "account_not_found", "username": uname}, started=started)
        return _err("UNAUTHORIZED", "Invalid credentials")

    if acc.get("status") != "active":
        code = "CONFLICT" if acc.get("status") == "locked" else "UNAUTHORIZED"
        _log(endpoint, code, meta={"reason": "account_status", "status": acc.get("status")}, started=started)
        return _err(code, "Account not available for login", status=acc.get("status"))

    # Ensure at most one active session per account_id; refresh existing if present else create
    active = None
    for s in sessions:
        if s.get("account_id") == acc.get("id") and s.get("status") == "active":
            active = s
            break

    # If existing active is revoked (shouldn't happen), do not reactivate
    if active and active.get("status") == "revoked":
        _log(endpoint, "INVALID_TRANSITION", credential_id=active.get("id"), meta={"reason": "revoked_cannot_reactivate"}, started=started)
        return _err("INVALID_TRANSITION", "Revoked session cannot be reactivated")

    # Create a cookie jar placeholder; must be plaintext here (encrypted string stored)
    cookie_payload = {
        "username": uname,
        "issued_at": now,
        "ua": user_agent.strip() if isinstance(user_agent, str) else None,
        "ip": ip_address.strip() if isinstance(ip_address, str) else None,
    }
    cookie_jar_encrypted = "enc:" + hashlib.sha256(json.dumps(cookie_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()

    if active:
        # refresh
        active["cookie_jar_encrypted"] = cookie_jar_encrypted
        active["user_agent"] = user_agent.strip() if isinstance(user_agent, str) else active.get("user_agent")
        active["ip_address"] = ip_address.strip() if isinstance(ip_address, str) else active.get("ip_address")
        active["last_verified_at"] = now
        active["updated_at"] = now
        # also update account last_login_at
        acc["last_login_at"] = now
        acc["updated_at"] = now
        try:
            _save("auth_sessions.json", sessions)
            _save("accounts.json", accounts)
        except Exception:
            _log(endpoint, "CONFLICT", credential_id=active.get("id"), meta={"reason": "persist_refresh_failed"}, started=started)
            return _err("CONFLICT", "Failed to refresh session")
        _log(endpoint, "ok", credential_id=active.get("id"), meta={"session": "refreshed", "account_id": acc.get("id")}, started=started)
        return {
            "session": {
                "id": active.get("id"),
                "account_id": active.get("account_id"),
                "status": active.get("status"),
                "user_agent": active.get("user_agent"),
                "ip_address": active.get("ip_address"),
                "last_verified_at": active.get("last_verified_at"),
                "expires_at": active.get("expires_at"),
                "updated_at": active.get("updated_at"),
                "created_at": active.get("created_at"),
            },
            "account": {"id": acc.get("id"), "platform": acc.get("platform"), "username": acc.get("username"), "status": acc.get("status")},
        }

    # If there are other active sessions for this account (shouldn't due to constraint), revoke extras
    for s in sessions:
        if s.get("account_id") == acc.get("id") and s.get("status") == "active":
            s["status"] = "revoked"
            s["updated_at"] = now

    sid = "sess_" + hashlib.sha256(f"{acc.get('id')}|{now}|{len(sessions)}".encode("utf-8")).hexdigest()[:16]
    srow = {
        "id": sid,
        "account_id": acc.get("id"),
        "status": "active",
        "cookie_jar_encrypted": cookie_jar_encrypted,
        "user_agent": user_agent.strip() if isinstance(user_agent, str) else None,
        "ip_address": ip_address.strip() if isinstance(ip_address, str) else None,
        "last_verified_at": now,
        "expires_at": None,
        "created_at": now,
        "updated_at": now,
    }
    sessions.append(srow)
    acc["last_login_at"] = now
    acc["updated_at"] = now

    try:
        _save("auth_sessions.json", sessions)
        _save("accounts.json", accounts)
    except Exception:
        _log(endpoint, "CONFLICT", credential_id=sid, meta={"reason": "persist_create_failed"}, started=started)
        return _err("CONFLICT", "Failed to create session")

    _log(endpoint, "ok", credential_id=sid, meta={"session": "created", "account_id": acc.get("id")}, started=started)
    return {
        "session": {
            "id": srow.get("id"),
            "account_id": srow.get("account_id"),
            "status": srow.get("status"),
            "user_agent": srow.get("user_agent"),
            "ip_address": srow.get("ip_address"),
            "last_verified_at": srow.get("last_verified_at"),
            "expires_at": srow.get("expires_at"),
            "updated_at": srow.get("updated_at"),
            "created_at": srow.get("created_at"),
        },
        "account": {"id": acc.get("id"), "platform": acc.get("platform"), "username": acc.get("username"), "status": acc.get("status")},
    }

def list_search_queries(keywords_contains=None, status=None, executed_from=None, executed_to=None, page=None, page_size=None, include_results=None, order_by=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")
    queries = _load("search_queries.json")
    results = _load("search_query_results.json")
    request_logs = _load("request_logs.json")

    # ---- auth context (ambient) ----
    def _pick_context():
        # Find ANY working active session + active account on rednote
        for s in sessions if isinstance(sessions, list) else []:
            if s.get("status") != "active":
                continue
            acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
            if not acc:
                continue
            if acc.get("platform") != "rednote":
                continue
            if acc.get("status") != "active":
                continue
            return acc, s
        return None, None

    acc, sess = _pick_context()

    def _append_log(status_str, error_code=None, error_message=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "endpoint": "list_search_queries",
            "account_id": acc.get("id") if acc else None,
            "session_id": sess.get("id") if sess else None,
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        }
        if isinstance(request_logs, list):
            request_logs.append(row)
            _save("request_logs.json", request_logs)

    # Enforce a simple rate limit if request_logs exists (observable dynamics)
    def _rate_limit_check():
        if not isinstance(request_logs, list) or not acc:
            return None
        window_s = 10
        limit_n = 60
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_created_at(v):
            if not isinstance(v, str) or not v:
                return None
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt

        recent = 0
        for r in request_logs:
            if r.get("account_id") != acc.get("id"):
                continue
            dt = _parse_created_at(r.get("created_at"))
            if dt and dt >= cutoff:
                recent += 1
        if recent >= limit_n:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_n)
        return None

    if not acc or not sess:
        _append_log("error", "UNAUTHORIZED", "No active authenticated session available for this operation.")
        return _err("UNAUTHORIZED", "No active authenticated session available for this operation.")

    rl = _rate_limit_check()
    if rl:
        _append_log("error", "RATE_LIMIT", rl["error"]["message"])
        return rl

    # ---- validation ----
    if keywords_contains is not None and not isinstance(keywords_contains, str):
        _append_log("error", "VALIDATION_ERROR", "keywords_contains must be a string.")
        return _err("VALIDATION_ERROR", "keywords_contains must be a string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "completed", "failed"):
            _append_log("error", "VALIDATION_ERROR", "status must be one of queued, running, completed, failed.")
            return _err("VALIDATION_ERROR", "status must be one of queued, running, completed, failed.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 20
    if include_results is None:
        include_results = False
    if order_by is None:
        order_by = "created_at_desc"

    if not isinstance(page, int) or page < 1:
        _append_log("error", "VALIDATION_ERROR", "page must be an integer >= 1.")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _append_log("error", "VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if not isinstance(include_results, bool):
        _append_log("error", "VALIDATION_ERROR", "include_results must be a boolean.")
        return _err("VALIDATION_ERROR", "include_results must be a boolean.")
    if order_by not in ("created_at_desc", "created_at_asc", "executed_at_desc", "executed_at_asc"):
        _append_log("error", "VALIDATION_ERROR", "order_by must be one of created_at_desc, created_at_asc, executed_at_desc, executed_at_asc.")
        return _err("VALIDATION_ERROR", "order_by must be one of created_at_desc, created_at_asc, executed_at_desc, executed_at_asc.")

    def _parse_dt_relaxed(val):
        # IMPORTANT: accept non-datetime strings WITHOUT error by treating them as "no filter"
        # (audit showed callers passed ids here; strict parsing caused false VALIDATION_ERROR)
        if val is None:
            return None
        if isinstance(val, datetime.datetime):
            dt = val
        elif isinstance(val, str):
            s = val.strip()
            if not s:
                return None
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                # Not a datetime -> ignore filter rather than error
                return None
        else:
            return None
        if getattr(dt, "tzinfo", None) is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt

    dt_from = _parse_dt_relaxed(executed_from)
    dt_to = _parse_dt_relaxed(executed_to)
    if dt_from and dt_to and dt_to < dt_from:
        _append_log("error", "VALIDATION_ERROR", "executed_to must be >= executed_from.")
        return _err("VALIDATION_ERROR", "executed_to must be >= executed_from.")

    def _parse_row_dt(v):
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt

    # ---- filter ----
    qrows = queries if isinstance(queries, list) else []
    filtered = []
    kw = (keywords_contains or "").strip().lower() if isinstance(keywords_contains, str) else None
    for q in qrows:
        if status and q.get("status") != status:
            continue
        if kw:
            k = q.get("keywords")
            if not isinstance(k, str) or kw not in k.lower():
                continue
        if dt_from or dt_to:
            exdt = _parse_row_dt(q.get("executed_at"))
            # If executed_at is null, it fails the range filter (typical semantics)
            if exdt is None:
                continue
            if dt_from and exdt < dt_from:
                continue
            if dt_to and exdt > dt_to:
                continue
        filtered.append(q)

    # ---- sort ----
    def _sort_key_created(q):
        dt = _parse_row_dt(q.get("created_at"))
        return dt or datetime.datetime.min

    def _sort_key_executed(q):
        dt = _parse_row_dt(q.get("executed_at"))
        return dt or datetime.datetime.min

    reverse = order_by.endswith("_desc")
    if order_by.startswith("created_at_"):
        filtered.sort(key=_sort_key_created, reverse=reverse)
    else:
        filtered.sort(key=_sort_key_executed, reverse=reverse)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = filtered[start:end]
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    # attach results if requested
    out_rows = []
    if include_results:
        res_rows = results if isinstance(results, list) else []
        by_qid = {}
        for r in res_rows:
            qid = r.get("query_id")
            if qid is None:
                continue
            by_qid.setdefault(qid, []).append(r)
        for q in page_rows:
            qid = q.get("id")
            rlist = by_qid.get(qid, [])
            # stable ordering by rank
            rlist = sorted(rlist, key=lambda x: x.get("rank", 0))
            qq = dict(q)
            qq["results"] = rlist
            out_rows.append(qq)
    else:
        out_rows = [dict(q) for q in page_rows]

    _append_log("ok", None, None)
    return {
        "data": out_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order_by": order_by,
        },
    }

def get_search_query(id, include_results=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    # Input validation
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id; must be a non-empty string.", field="id")
    if include_results is None:
        include_results = True
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean.", field="include_results")

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")
    queries = _load("search_queries.json")
    qry_results = _load("search_query_results.json")
    notes = _load("notes.json")
    request_logs = _load("request_logs.json")

    if not isinstance(accounts, list): accounts = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(queries, list): queries = []
    if not isinstance(qry_results, list): qry_results = []
    if not isinstance(notes, list): notes = []
    if not isinstance(request_logs, list): request_logs = []

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Ambient auth: choose ANY workable active account+session combination.
    def _pick_context():
        for s in sessions:
            if s.get("status") != "active":
                continue
            acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
            if not acc:
                continue
            if acc.get("platform") != "rednote":
                continue
            if acc.get("status") != "active":
                continue
            return acc, s
        # If no active session, still allow reads if there exists an active rednote account at all.
        acc = next((a for a in accounts if a.get("platform") == "rednote" and a.get("status") == "active"), None)
        return acc, None

    acc, sess = _pick_context()

    def _append_log(status_str, error_code=None, error_message=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        request_logs.append({
            "id": rid,
            "endpoint": "get_search_query",
            "account_id": acc.get("id") if isinstance(acc, dict) else None,
            "session_id": sess.get("id") if isinstance(sess, dict) else None,
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        })
        _save("request_logs.json", request_logs)

    def _rate_limit_check():
        # 60 requests / 10 seconds per account (if account known); otherwise global
        window_s = 10
        limit_n = 60
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _match_row(r):
            if r.get("endpoint") != "get_search_query":
                return False
            ts = _parse_iso(r.get("created_at"))
            if not ts or ts < cutoff:
                return False
            if isinstance(acc, dict) and acc.get("id"):
                return r.get("account_id") == acc.get("id")
            return True  # global if no account context
        recent = sum(1 for r in request_logs if isinstance(r, dict) and _match_row(r))
        if recent >= limit_n:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_n)
        return None

    rl = _rate_limit_check()
    if rl:
        _append_log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    if not isinstance(acc, dict):
        # No workable context at all
        _append_log("error", "UNAUTHORIZED", "No active account context available.")
        return _err("UNAUTHORIZED", "No active account context available.")

    q = next((r for r in queries if isinstance(r, dict) and r.get("id") == id), None)
    if not q:
        _append_log("error", "NOT_FOUND", "Search query not found.")
        return _err("NOT_FOUND", "Search query not found.", id=id)

    out = dict(q)

    if include_results:
        # Filter results by query_id and sort by rank ascending
        rows = [r for r in qry_results if isinstance(r, dict) and r.get("query_id") == id]
        rows.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

        # Optionally attach minimal note info if present (do not fabricate)
        note_by_id = {n.get("id"): n for n in notes if isinstance(n, dict) and isinstance(n.get("id"), str)}
        enriched = []
        for r in rows:
            rr = dict(r)
            n = note_by_id.get(r.get("note_id"))
            if isinstance(n, dict):
                rr["note"] = {
                    "id": n.get("id"),
                    "url": n.get("url"),
                    "title": n.get("title"),
                    "author_name": n.get("author_name"),
                    "status": n.get("status"),
                    "published_at": n.get("published_at"),
                }
            enriched.append(rr)
        out["results"] = enriched
        out["results_meta"] = {"total": len(rows)}

    _append_log("ok", None, None)
    return {"data": out}

def list_notes(platform=None, status=None, url=None, note_key=None, author_name_contains=None, tag=None, published_from=None, published_to=None, page=None, page_size=None, order_by=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")

    def _pick_context():
        for s in sessions:
            if s.get("status") != "active":
                continue
            acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
            if not acc:
                continue
            if acc.get("platform") != "rednote":
                continue
            if acc.get("status") != "active":
                continue
            return acc, s
        return None, None

    acc, sess = _pick_context()
    if not acc or not sess:
        return _err("UNAUTHORIZED", "No active authenticated session available for this operation.")

    request_logs = _load("request_logs.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "BAD"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return "BAD"

    def _log(status_str, error_code=None, error_message=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "list_notes",
            "account_id": acc.get("id"),
            "session_id": sess.get("id"),
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    window_sec = 60
    limit_rl = 60
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
    recent = 0
    for r in request_logs:
        if r.get("account_id") != acc.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if isinstance(ts, datetime.datetime) and ts >= cutoff:
            recent += 1
    if recent >= limit_rl:
        _log("error", "RATE_LIMIT", "Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit_rl, window_seconds=window_sec)

    # defaults
    if page is None:
        page = 1
    if page_size is None:
        page_size = 20
    if order_by is None:
        order_by = "updated_at_desc"

    # validate
    if platform is not None:
        if not isinstance(platform, str) or platform not in ["xhs"]:
            _log("error", "VALIDATION_ERROR", "invalid platform")
            return _err("VALIDATION_ERROR", "platform must be 'xhs' if provided.")
    if status is not None:
        if not isinstance(status, str) or status not in ["discovered", "fetching", "available", "unavailable", "deleted"]:
            _log("error", "VALIDATION_ERROR", "invalid status")
            return _err("VALIDATION_ERROR", "status must be one of discovered/fetching/available/unavailable/deleted.")
    if url is not None and (not isinstance(url, str) or not url.strip()):
        _log("error", "VALIDATION_ERROR", "url must be string")
        return _err("VALIDATION_ERROR", "url must be a non-empty string if provided.")
    if note_key is not None and (not isinstance(note_key, str) or not note_key.strip()):
        _log("error", "VALIDATION_ERROR", "note_key must be string")
        return _err("VALIDATION_ERROR", "note_key must be a non-empty string if provided.")
    if author_name_contains is not None and not isinstance(author_name_contains, str):
        _log("error", "VALIDATION_ERROR", "author_name_contains must be string")
        return _err("VALIDATION_ERROR", "author_name_contains must be a string if provided.")
    if tag is not None and (not isinstance(tag, str) or not tag.strip()):
        _log("error", "VALIDATION_ERROR", "tag must be string")
        return _err("VALIDATION_ERROR", "tag must be a non-empty string if provided.")
    if not isinstance(page, int) or page < 1:
        _log("error", "VALIDATION_ERROR", "page out of range")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", "VALIDATION_ERROR", "page_size out of range")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if not isinstance(order_by, str) or order_by not in ["updated_at_desc", "updated_at_asc", "published_at_desc", "published_at_asc", "created_at_desc", "created_at_asc"]:
        _log("error", "VALIDATION_ERROR", "invalid order_by")
        return _err("VALIDATION_ERROR", "order_by must be one of updated_at_desc/updated_at_asc/published_at_desc/published_at_asc/created_at_desc/created_at_asc.")

    dt_from = _parse_dt(published_from)
    if dt_from == "BAD":
        _log("error", "VALIDATION_ERROR", "published_from must be ISO 8601")
        return _err("VALIDATION_ERROR", "published_from must be an ISO 8601 datetime string.")
    dt_to = _parse_dt(published_to)
    if dt_to == "BAD":
        _log("error", "VALIDATION_ERROR", "published_to must be an ISO 8601 datetime string.")
    if isinstance(dt_from, datetime.datetime) and isinstance(dt_to, datetime.datetime) and dt_from > dt_to:
        _log("error", "VALIDATION_ERROR", "published_from after published_to")
        return _err("VALIDATION_ERROR", "published_from must be <= published_to.")

    notes = _load("notes.json")

    # tool platform 'xhs' maps to stored platform 'rednote'
    store_platform = None
    if platform == "xhs":
        store_platform = "rednote"

    def _dt_or_none(s):
        if s is None or not isinstance(s, str):
            return None
        p = _parse_dt(s)
        return p if isinstance(p, datetime.datetime) else None

    anc = author_name_contains.lower() if isinstance(author_name_contains, str) else None

    filtered = []
    for n in notes:
        if store_platform is not None and n.get("platform") != store_platform:
            continue
        if status is not None and n.get("status") != status:
            continue
        if url is not None and n.get("url") != url:
            continue
        if note_key is not None and n.get("note_key") != note_key:
            continue
        if anc is not None:
            an = n.get("author_name")
            if not isinstance(an, str) or anc not in an.lower():
                continue
        if tag is not None:
            tags = n.get("tags")
            if not isinstance(tags, list) or tag not in tags:
                continue
        if isinstance(dt_from, datetime.datetime) or isinstance(dt_to, datetime.datetime):
            pub = _dt_or_none(n.get("published_at"))
            if pub is None:
                continue
            if isinstance(dt_from, datetime.datetime) and pub < dt_from:
                continue
            if isinstance(dt_to, datetime.datetime) and pub > dt_to:
                continue
        filtered.append(n)

    def _sort_key(n):
        ua = _dt_or_none(n.get("updated_at")) or datetime.datetime.min
        ca = _dt_or_none(n.get("created_at")) or datetime.datetime.min
        pa = _dt_or_none(n.get("published_at")) or datetime.datetime.min
        if order_by.startswith("updated_at"):
            return ua
        if order_by.startswith("published_at"):
            return pa
        return ca

    reverse = order_by.endswith("_desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = filtered[start:end]
    has_more = end < total

    _log("ok")
    return {
        "data": page_rows,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more
        }
    }

def update_note(id, status=None, title=None, author_name=None, content_text=None, content_html=None, media_urls=None, tags=None, published_at=None, fetch_error=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id; must be a non-empty string.", field="id")

    allowed_status = {"discovered", "fetching", "available", "unavailable", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(list(allowed_status)))
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string.", field="title")
    if author_name is not None and not isinstance(author_name, str):
        return _err("VALIDATION_ERROR", "author_name must be a string.", field="author_name")
    if content_text is not None and not isinstance(content_text, str):
        return _err("VALIDATION_ERROR", "content_text must be a string.", field="content_text")
    if content_html is not None and not isinstance(content_html, str):
        return _err("VALIDATION_ERROR", "content_html must be a string.", field="content_html")
    if fetch_error is not None and not isinstance(fetch_error, str):
        return _err("VALIDATION_ERROR", "fetch_error must be a string.", field="fetch_error")

    def _validate_str_list(v, field):
        if v is None:
            return None
        if not isinstance(v, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array of strings.", field=field)
        for i, x in enumerate(v):
            if not isinstance(x, str):
                return _err("VALIDATION_ERROR", f"{field}[{i}] must be a string.", field=field)
        return None

    e = _validate_str_list(media_urls, "media_urls")
    if e: return e
    e = _validate_str_list(tags, "tags")
    if e: return e

    # published_at should be ISO 8601 string if provided (store as-is but validate parseable)
    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", "published_at must be a non-empty ISO 8601 string.", field="published_at")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                datetime.datetime.fromisoformat(ss[:-1])
            else:
                datetime.datetime.fromisoformat(ss)
            return None
        except Exception:
            return _err("VALIDATION_ERROR", "published_at must be ISO 8601 parseable.", field="published_at")

    e = _parse_iso(published_at)
    if e: return e

    accounts = _load("accounts.json")
    sessions = _load("auth_sessions.json")
    notes = _load("notes.json")
    request_logs = _load("request_logs.json")

    if not isinstance(accounts, list): accounts = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(notes, list): notes = []
    if not isinstance(request_logs, list): request_logs = []

    # Ambient auth context resolution
    def _pick_context():
        for s in sessions:
            if s.get("status") != "active":
                continue
            acc = next((a for a in accounts if a.get("id") == s.get("account_id")), None)
            if not acc:
                continue
            if acc.get("platform") != "rednote":
                continue
            if acc.get("status") != "active":
                continue
            return acc, s
        acc = next((a for a in accounts if a.get("platform") == "rednote" and a.get("status") == "active"), None)
        return acc, None

    acc, sess = _pick_context()

    def _append_log(status_str, error_code=None, error_message=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        request_logs.append({
            "id": rid,
            "endpoint": "update_note",
            "account_id": acc.get("id") if isinstance(acc, dict) else None,
            "session_id": sess.get("id") if isinstance(sess, dict) else None,
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        })
        _save("request_logs.json", request_logs)

    def _rate_limit_check():
        window_s = 10
        limit_n = 30
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_created_at(v):
            if not isinstance(v, str) or not v:
                return None
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1])
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None

        def _match_row(r):
            if r.get("endpoint") != "update_note":
                return False
            ts = _parse_created_at(r.get("created_at"))
            if not ts or ts < cutoff:
                return False
            if isinstance(acc, dict) and acc.get("id"):
                return r.get("account_id") == acc.get("id")
            return True

        recent = sum(1 for r in request_logs if isinstance(r, dict) and _match_row(r))
        if recent >= limit_n:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=window_s, limit=limit_n)
        return None

    rl = _rate_limit_check()
    if rl:
        _append_log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    if not isinstance(acc, dict):
        _append_log("error", "UNAUTHORIZED", "No active account context available.")
        return _err("UNAUTHORIZED", "No active account context available.")

    # Locate note by primary key id (do not interpret other ids)
    note = next((n for n in notes if isinstance(n, dict) and n.get("id") == id), None)
    if not note:
        _append_log("error", "NOT_FOUND", "Note not found.")
        return _err("NOT_FOUND", "Note not found.", id=id)

    # Enforce lifecycle transitions if status is changing
    transitions = {
        "discovered": {"fetching", "unavailable"},
        "fetching": {"available", "unavailable"},
        "available": {"fetching", "deleted", "unavailable"},
        "unavailable": {"fetching", "deleted"},
        "deleted": set(),
    }

    current_status = note.get("status")
    if not isinstance(current_status, str) or current_status not in transitions:
        # datastore corruption / unexpected
        _append_log("error", "CONFLICT", "Note has an invalid current status.")
        return _err("CONFLICT", "Note has an invalid current status.", current_status=current_status)

    if status is not None and status != current_status:
        # Business rule: deleted cannot go back to available (already covered by transitions), and deleted is terminal.
        if current_status == "deleted":
            _append_log("error", "CONFLICT", "Illegal status transition: deleted is terminal and cannot be changed.")
            return _err("CONFLICT", "Illegal status transition: deleted is terminal and cannot be changed.",
                        rule="notes.status transitions; deleted -> (none)", from_status=current_status, to_status=status)
        if status not in transitions.get(current_status, set()):
            _append_log("error", "CONFLICT", "Illegal status transition.")
            return _err("CONFLICT", "Illegal status transition.",
                        rule="notes.status lifecycle transitions", from_status=current_status, to_status=status)

    # Apply updates (only provided fields)
    changed = False
    writable_fields = {
        "title": title,
        "author_name": author_name,
        "content_text": content_text,
        "content_html": content_html,
        "media_urls": media_urls,
        "tags": tags,
        "published_at": published_at,
        "fetch_error": fetch_error,
    }

    for k, v in writable_fields.items():
        if v is not None:
            # Normalize arrays to lists (already validated)
            note[k] = v
            changed = True

    if status is not None and status != current_status:
        note["status"] = status
        changed = True
        # Update fetch timestamps/fields semantics
        if status == "available":
            note["last_fetched_at"] = now_iso
            note["fetch_error"] = None
        elif status == "unavailable":
            # keep last_fetched_at unchanged; allow fetch_error set above
            pass
        elif status == "fetching":
            # entering fetching clears previous error to reflect retry intent
            note["fetch_error"] = None

    if not changed:
        _append_log("error", "CONFLICT", "No fields to update.")
        return _err("CONFLICT", "No fields to update.")

    note["updated_at"] = now_iso

    _save("notes.json", notes)
    _append_log("ok", None, None)
    return {"data": note}

def list_accounts(platform=None, status=None, username_contains=None, page=None, page_size=None, order_by=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0132000" if __import__("os").path.isdir("./environment_mix/0132000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging + quota/rate limit helpers ----
    def _ensure_request_logs_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log_request(credential_id, endpoint, status_code, error_code=None, extra=None):
        fname = _ensure_request_logs_file()
        logs = _load(fname)
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "rql_" + str(int(time.time() * 1000)) + "_" + str(len(logs) + 1),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now
        }
        if isinstance(extra, dict) and extra:
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                # allow "YYYY-MM-DDTHH:MM:SS" or with fractional
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Global rate limit (offline model): 60 req/min per resolved credential (or "ambient")
    RATE_LIMIT_PER_MIN = 60

    def _check_rate_limit(credential_id):
        fname = _ensure_request_logs_file()
        logs = _load(fname)
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("endpoint") != "list_accounts":
                continue
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt < RATE_LIMIT_PER_MIN, cnt

    # ---- Ambient auth resolution ----
    # No explicit credential parameter; select any working "account context".
    # For this server, viewing accounts requires there exists at least one active (or locked) account
    # in the datastore for the target platform.
    accounts = _load("accounts.json")

    # ---- Input validation ----
    # Tool enum uses "xhs"; schema uses "rednote". Map xhs -> rednote for datastore.
    platform_map = {"xhs": "rednote", "rednote": "rednote"}

    if platform is not None:
        if not isinstance(platform, str):
            _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "platform must be a string")
        if platform not in ("xhs",):
            _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "platform must be one of: xhs")
    if status is not None:
        if not isinstance(status, str):
            _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "locked", "disabled"):
            _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, locked, disabled")
    if username_contains is not None and not isinstance(username_contains, str):
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "username_contains must be a string")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20
    if order_by is None:
        order_by = "updated_at_desc"

    if not isinstance(page, int):
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer")
    if page < 1:
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be >= 1")

    if not isinstance(page_size, int):
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer")
    if page_size < 1 or page_size > 100:
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100")

    if not isinstance(order_by, str):
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_by must be a string")
    if order_by not in (
        "updated_at_desc", "updated_at_asc",
        "last_login_at_desc", "last_login_at_asc",
        "created_at_desc", "created_at_asc"
    ):
        _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_by is invalid")

    ds_platform = None
    if platform is not None:
        ds_platform = platform_map.get(platform)
        if ds_platform is None:
            _log_request("ambient", "list_accounts", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported platform mapping")

    # ---- Authorization check (ambient) ----
    # Must not refuse merely because signature has no auth parameter.
    # Consider authorized if there exists at least one account for the requested platform (or any platform if none specified).
    auth_ok = False
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if ds_platform is not None and a.get("platform") != ds_platform:
            continue
        # Any known account grants listing permission in this offline store model
        auth_ok = True
        break

    if not auth_ok:
        _log_request("ambient", "list_accounts", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available to list accounts")

    credential_id = "ambient"

    # ---- Rate limiting ----
    ok_rl, recent_cnt = _check_rate_limit(credential_id)
    if not ok_rl:
        _log_request(credential_id, "list_accounts", 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests", retry_after_seconds=60, limit_per_minute=RATE_LIMIT_PER_MIN, recent_requests=recent_cnt)

    # ---- Filtering ----
    rows = []
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if ds_platform is not None and a.get("platform") != ds_platform:
            continue
        if status is not None and a.get("status") != status:
            continue
        if username_contains is not None:
            un = a.get("username")
            if not isinstance(un, str):
                continue
            if username_contains.lower() not in un.lower():
                continue
        rows.append(a)

    # ---- Sorting ----
    def _key_dt(field):
        def k(r):
            dt = _parse_dt(r.get(field))
            # None sorts last for desc/asc by using min/max sentinels
            if dt is None:
                return datetime.datetime.min
            return dt
        return k

    if order_by.startswith("updated_at_"):
        keyf = _key_dt("updated_at")
        reverse = order_by.endswith("_desc")
    elif order_by.startswith("last_login_at_"):
        keyf = _key_dt("last_login_at")
        reverse = order_by.endswith("_desc")
    else:
        keyf = _key_dt("created_at")
        reverse = order_by.endswith("_desc")

    # For None values, we used datetime.min; but for ascending we want None last.
    # Adjust: when ascending, treat None as datetime.max; when descending, treat None as datetime.min.
    def _key_dt_none_last(field, reverse_flag):
        def k(r):
            dt = _parse_dt(r.get(field))
            if dt is None:
                return datetime.datetime.min if reverse_flag else datetime.datetime.max
            return dt
        return k

    if order_by.startswith("updated_at_"):
        keyf = _key_dt_none_last("updated_at", reverse)
    elif order_by.startswith("last_login_at_"):
        keyf = _key_dt_none_last("last_login_at", reverse)
    else:
        keyf = _key_dt_none_last("created_at", reverse)

    try:
        rows.sort(key=keyf, reverse=reverse)
    except TypeError:
        # mixed types in store; fall back to stable string sort on iso
        def _iso(field):
            def k(r):
                v = r.get(field)
                return v if isinstance(v, str) else ""
            return k
        if order_by.startswith("updated_at_"):
            rows.sort(key=_iso("updated_at"), reverse=reverse)
        elif order_by.startswith("last_login_at_"):
            rows.sort(key=_iso("last_login_at"), reverse=reverse)
        else:
            rows.sort(key=_iso("created_at"), reverse=reverse)

    # ---- Pagination ----
    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end] if start < total else []
    has_more = end < total

    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more
        }
    }

    _log_request(credential_id, "list_accounts", 200, None, extra={"result_count": len(page_rows)})
    return resp
